SELECT MAX(total_spent) AS highest_event_spend
FROM (
    SELECT SUM(`spent`) AS total_spent
    FROM `Budget`
    GROUP BY `link_to_event`
);

SELECT `type`
FROM `event`
WHERE `location` = 'MU 215';

SELECT c.Text, u.DisplayName
FROM comments c JOIN posts p ON c.PostId = p.Id LEFT JOIN users u ON c.UserId = u.Id 
WHERE p.Title = 'Analysing wind data with R' ORDER BY c.CreationDate DESC LIMIT 10;

SELECT `text`
FROM `cards`
WHERE `name` = 'Benalish Knight';
